-- The end-of-night message goes until it has gone (#179; #86). `service_days.report_sent_at` is set
-- once, by `service_day.report_sent`, when Telegram accepts the day's message. Generated by
-- drizzle-kit, then this comment and the backfill added by hand: every day closed before this
-- change carries its close time, so no old night is sent again. Numbered 0036 because the journal
-- guard needs consecutive numbers and #164 (Part 2) has not merged its own 0036: whoever merges
-- second renumbers (file, journal tag and idx, snapshot).
ALTER TABLE "restro"."service_days" ADD COLUMN "report_sent_at" timestamp with time zone;--> statement-breakpoint
UPDATE "restro"."service_days" SET "report_sent_at" = "closed_at";
